---@type Engine.Modules.Atlas.SpriteManager
local SpriteManager = CS.Engine.Modules.Atlas.SpriteManager.Instance

local SpriteRenderer = CS.UnityEngine.SpriteRenderer


---背景轨道的片段,用于填充背景图片
---@class SpriteTrackSegment:TrackSegment
local SpriteTrackSegment = Class("SpriteTrackSegment",import("Game.Activity.ParkourGame.MainGame.Tracks.TrackSegment"))

function SpriteTrackSegment:__init(gameobject,length)
    self.super.__init(self,gameobject,length)
    self.spriteRender = CfUtils.GetOrAddComponent(gameobject,typeof(SpriteRenderer))
    self.spriteRender.drawMode = CS.UnityEngine.SpriteDrawMode.Sliced
    self.spriteRender.size = Vector2.New(self.length,self.length/1.5)
end


function SpriteTrackSegment:RefreshContent(imgPath)
    SpriteManager:GetSpriteByOwner(imgPath, self.gameobject, function (sprite)
        if isNotNull(sprite) then
            self.spriteRender.sprite = sprite
            self.spriteRender.size = Vector2.New(self.length,self.length/1.5)
        end
    end)
    
end


return SpriteTrackSegment